-- 216 (16/11/2026, lô 52): 21 bài Viết TCF cho cây Luyện thi TCF, 7 miễn phí, 14 VIP.
-- Sinh bởi scripts/nhap/lo52_viet_tcf.mjs. Câu viết mang payload.tache; AI chấm bằng cham-tcf (luyenTap). Chạy lại an toàn.
-- TCF-PE-1 #1 Écriture TCF : message à des amis (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe01', 'practice', 'Écriture TCF : message à des amis', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Vous venez d''emménager dans un nouvel appartement. Vous écrivez un message à vos amis pour leur décrire votre logement et votre quartier, et pour les inviter à venir vous voir. (60 mots minimum, 120 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• emménager (verbe) : dọn đến ở\n• lumineux (adjectif) : nhiều ánh sáng\n• en bas de chez moi : ngay dưới nhà tôi\n• fêter (verbe) : ăn mừng","explications":"• Tâche 1 chấm cả việc làm ĐỦ các ý của đề: gạch dưới từng động từ của đề (décrire, inviter…) và kiểm lại trước khi nộp.\n• Mở và đóng thư đúng giọng: Salut / Bises cho bạn bè, Bonjour / Cordialement cho người lạ.","kyNang":"TCF-PE-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T12:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe01q01', 'lo52tcfpe01', 1, 'qcm', 'À qui écrivez-vous ?', '{"options":["À vos nouveaux voisins de palier.","À votre propriétaire.","À des amis."]}'::jsonb, '{"answer":2}'::jsonb, 'Đề ghi « un message à vos amis »: giọng thân mật. Viết cho nhiều bạn thì dùng « vous » số nhiều.'),
  ('lo52tcfpe01q02', 'lo52tcfpe01', 2, 'qcm', 'Que devez-vous faire dans ce message ?', '{"options":["Décrire le logement et le quartier, puis inviter.","Demander de l''aide pour porter les cartons.","Raconter le déménagement."]}'::jsonb, '{"answer":0}'::jsonb, 'Đề có hai việc: « leur décrire votre logement et votre quartier » và « pour les inviter à venir vous voir ».'),
  ('lo52tcfpe01q03', 'lo52tcfpe01', 3, 'qcm', 'Quelle longueur est acceptée ?', '{"options":["Entre 60 et 120 mots.","Au moins 120 mots, sans maximum.","Moins de 60 mots, pour être bref."]}'::jsonb, '{"answer":0}'::jsonb, '« 60 mots minimum, 120 mots maximum »: quá ngắn hay quá dài đều bị trừ ở tiêu chí phù hợp đề.'),
  ('lo52tcfpe01q04', 'lo52tcfpe01', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (60 à 120 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Vous venez d''emménager dans un nouvel appartement. Vous écrivez un message à vos amis pour leur décrire votre logement et votre quartier, et pour les inviter à venir vous voir. (60 mots minimum, 120 mots maximum)</p>","tache":1}'::jsonb, '{"model":"Salut à tous !\nÇa y est, j''ai enfin déménagé ! Mon nouvel appartement est au troisième étage d''un vieil immeuble, rue des Lilas. Il est petit mais très lumineux : il y a un salon avec un balcon, une chambre et une cuisine toute neuve. Le quartier est calme et vivant à la fois : il y a un marché le samedi, une boulangerie en bas de chez moi et un grand parc à cinq minutes. Je vous invite à dîner samedi 14 à 19 h pour fêter ça. Dites-moi si vous pouvez venir !\nBises,\nLinh"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-1 #2 Écriture TCF : courriel à un collègue (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe02', 'practice', 'Écriture TCF : courriel à un collègue', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Vous ne pourrez pas aller à une réunion importante demain. Vous écrivez un courriel à votre collègue pour lui expliquer pourquoi, lui dire ce que vous avez préparé et lui demander de vous remplacer. (60 mots minimum, 120 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• joignable (adjectif) : liên lạc được\n• le dossier partagé : thư mục dùng chung\n• à ma place : thay tôi\n• remplacer (verbe) : thay thế","explications":"• Đề có ba động từ (expliquer, dire, demander) thì bài cần ba ý rõ ràng, mỗi ý một hai câu.\n• Dòng « Objet » ngắn giúp thư nhìn đúng kiểu email công việc.","kyNang":"TCF-PE-1","vong":"on","thuTu":2}'::jsonb, '2026-11-16T12:00:01.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe02q01', 'lo52tcfpe02', 1, 'qcm', 'Quel registre convient ?', '{"options":["Poli mais simple, comme entre collègues.","Très familier.","Très administratif."]}'::jsonb, '{"answer":0}'::jsonb, 'Viết cho « votre collègue »: lịch sự, gọn, không cần văn phong hành chính.'),
  ('lo52tcfpe02q02', 'lo52tcfpe02', 2, 'qcm', 'Combien d''informations faut-il donner ?', '{"options":["Deux : la raison de l''absence et la date de votre retour au bureau.","Une seule : la raison de votre absence demain.","Trois : la raison, ce qui est prêt, la demande."]}'::jsonb, '{"answer":2}'::jsonb, 'Đề đòi « lui expliquer pourquoi », « lui dire ce que vous avez préparé » và « lui demander de vous remplacer ».'),
  ('lo52tcfpe02q03', 'lo52tcfpe02', 3, 'qcm', 'Quelle formule de fin est la plus adaptée ?', '{"options":["Gros bisous, je t''adore !","Je vous prie d''agréer mes salutations distinguées.","Merci d''avance, à bientôt."]}'::jsonb, '{"answer":2}'::jsonb, 'Giữa đồng nghiệp, « Merci d''avance, à bientôt » vừa lịch sự vừa tự nhiên. Công thức kia trang trọng quá, còn « Gros bisous » thì quá thân mật.'),
  ('lo52tcfpe02q04', 'lo52tcfpe02', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (60 à 120 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Vous ne pourrez pas aller à une réunion importante demain. Vous écrivez un courriel à votre collègue pour lui expliquer pourquoi, lui dire ce que vous avez préparé et lui demander de vous remplacer. (60 mots minimum, 120 mots maximum)</p>","tache":1}'::jsonb, '{"model":"Objet : réunion de demain\nBonjour Clara,\nJe suis désolé, mais je ne pourrai pas venir à la réunion avec le client demain matin : mon fils est malade et je dois rester avec lui. J''ai déjà préparé la présentation et le budget, tu trouveras les deux fichiers dans le dossier partagé du projet. Est-ce que tu pourrais présenter à ma place ? Tu connais bien le dossier, je suis sûr que tout se passera bien. Je reste joignable par téléphone si tu as une question.\nMerci d''avance, à bientôt,\nMinh"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-2 #1 Écriture TCF : témoignage sur une rencontre (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe03', 'practice', 'Écriture TCF : témoignage sur une rencontre', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Le site de votre association de quartier publie des témoignages sur le thème « Une rencontre qui a changé ma vie ». Vous racontez une rencontre importante et vous expliquez ce qu''elle vous a apporté. (120 mots minimum, 150 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un témoignage : bài chia sẻ trải nghiệm\n• apporter (verbe) : mang lại\n• naître (verbe) : nảy sinh\n• à mon tour : đến lượt tôi","explications":"• Chia bài làm hai đoạn: đoạn kể (chuyện gì, ở đâu, khi nào) và đoạn nhận xét (điều mình rút ra).\n• Thiếu đoạn nhận xét thì tâche 2 khó vượt mức B1, dù câu chữ đúng hết.","kyNang":"TCF-PE-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T12:00:02.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe03q01', 'lo52tcfpe03', 1, 'qcm', 'Qui va lire votre texte ?', '{"options":["Seulement la personne que vous avez rencontrée.","Le président de l''association, en privé.","Les membres et les visiteurs du site."]}'::jsonb, '{"answer":2}'::jsonb, 'Bài đăng trên « Le site de votre association de quartier »: nhiều người đọc, không phải thư riêng.'),
  ('lo52tcfpe03q02', 'lo52tcfpe03', 2, 'qcm', 'Que faut-il ajouter au récit ?', '{"options":["La biographie de la personne.","Des conseils pour se faire des amis.","Ce que cette rencontre vous a apporté."]}'::jsonb, '{"answer":2}'::jsonb, 'Ngoài kể, đề đòi « vous expliquez ce qu''elle vous a apporté »: phần nhận xét, cảm nghĩ của bạn.'),
  ('lo52tcfpe03q03', 'lo52tcfpe03', 3, 'qcm', 'Quels temps utiliser pour raconter ?', '{"options":["Le passé composé et l''imparfait.","Seulement le présent de l''indicatif.","Le futur simple et le conditionnel présent."]}'::jsonb, '{"answer":0}'::jsonb, 'Đề nói « Vous racontez une rencontre importante »: chuyện đã qua, dùng passé composé cho sự việc, imparfait cho bối cảnh.'),
  ('lo52tcfpe03q04', 'lo52tcfpe03', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 150 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Le site de votre association de quartier publie des témoignages sur le thème « Une rencontre qui a changé ma vie ». Vous racontez une rencontre importante et vous expliquez ce qu''elle vous a apporté. (120 mots minimum, 150 mots maximum)</p>","tache":2}'::jsonb, '{"model":"Il y a cinq ans, je venais d''arriver en France et je ne connaissais personne. Un soir, à la bibliothèque, une dame âgée m''a demandé de l''aider à utiliser l''ordinateur. Elle s''appelait Odette et elle avait quatre-vingts ans. Pour me remercier, elle m''a proposé de corriger mon français une fois par semaine, autour d''un thé. Pendant deux ans, nous nous sommes vues tous les mercredis.\nCette rencontre m''a apporté bien plus qu''un meilleur niveau de français. Grâce à Odette, j''ai compris que l''on peut apprendre à tout âge et qu''une amitié peut naître entre deux personnes très différentes. Aujourd''hui, à mon tour, j''aide chaque semaine des personnes âgées de mon quartier avec leur téléphone. C''est ma façon de lui dire merci."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-2 #2 Écriture TCF : article sur un événement (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe04', 'practice', 'Écriture TCF : article sur un événement', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Vous avez participé à un événement (festival, salon, compétition sportive…) dans votre ville. Vous écrivez un article pour le journal en ligne de votre entreprise : vous racontez cet événement et vous donnez votre opinion pour encourager, ou non, vos collègues à y participer l''année prochaine. (120 mots minimum, 150 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un salon : hội chợ, triển lãm\n• chaleureux (adjectif) : ấm áp\n• recommander vivement : rất khuyên\n• en dehors du bureau : ngoài giờ làm việc","explications":"• Bài báo nên có tiêu đề ngắn nêu luôn ý kiến (« à refaire ! », « une déception »).\n• Một ý trái chiều nhỏ (« Seul petit regret ») làm nhận xét đáng tin hơn.","kyNang":"TCF-PE-2","vong":"on","thuTu":2}'::jsonb, '2026-11-16T12:00:03.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe04q01', 'lo52tcfpe04', 1, 'qcm', 'Quel est l''objectif de l''article ?', '{"options":["Vendre des billets pour la prochaine édition de l''événement.","Conseiller les collègues pour l''an prochain.","Se plaindre officiellement auprès des organisateurs."]}'::jsonb, '{"answer":1}'::jsonb, 'Đề nói « pour encourager, ou non, vos collègues à y participer l''année prochaine ».'),
  ('lo52tcfpe04q02', 'lo52tcfpe04', 2, 'qcm', 'Votre opinion doit-elle être positive ?', '{"options":["Non, elle peut être positive ou négative.","Non, l''article doit rester totalement neutre.","Oui, il faut toujours encourager les collègues."]}'::jsonb, '{"answer":0}'::jsonb, '« encourager, ou non »: bạn được chọn khen hay chê, miễn là có lý do.'),
  ('lo52tcfpe04q03', 'lo52tcfpe04', 3, 'qcm', 'Qu''est-ce qui rend l''article plus convaincant ?', '{"options":["Des phrases très longues et très compliquées.","Des détails précis et un exemple vécu.","La liste complète de tous les participants de l''événement."]}'::jsonb, '{"answer":1}'::jsonb, 'Nhận xét kèm chi tiết thật thuyết phục hơn lời khen chung chung. Đề hỏi « vous racontez cet événement »: kể bằng chi tiết cụ thể.'),
  ('lo52tcfpe04q04', 'lo52tcfpe04', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 150 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Vous avez participé à un événement (festival, salon, compétition sportive…) dans votre ville. Vous écrivez un article pour le journal en ligne de votre entreprise : vous racontez cet événement et vous donnez votre opinion pour encourager, ou non, vos collègues à y participer l''année prochaine. (120 mots minimum, 150 mots maximum)</p>","tache":2}'::jsonb, '{"model":"Le Salon du livre de Lille : à refaire !\nLe mois dernier, avec trois collègues du service comptable, j''ai passé une journée au Salon du livre de Lille. Plus de deux cents auteurs étaient présents et l''ambiance était chaleureuse. J''ai assisté à une rencontre passionnante avec une autrice de romans policiers, puis à un atelier d''écriture où nous avons inventé une histoire à plusieurs.\nJe recommande vivement cet événement. D''abord, il est accessible à tous : l''entrée coûte seulement cinq euros. Ensuite, c''est une excellente occasion de mieux connaître ses collègues en dehors du bureau. Seul petit regret : il y avait beaucoup de monde l''après-midi, il vaut donc mieux arriver tôt. L''année prochaine, pourquoi ne pas y aller en groupe ?"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-3 #1 Écriture TCF : le téléphone à l'école (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe05', 'practice', 'Écriture TCF : le téléphone à l''école', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Vous participez à un forum sur le thème : « Faut-il interdire les téléphones portables à l''école ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Depuis que notre collège a interdit les portables, les élèves se parlent à nouveau pendant la récréation. Les cas de harcèlement en ligne ont aussi diminué. » <em>Sandrine, professeure de mathématiques</em></p><p><strong>Document 2</strong> : « Interdire, c''est facile. Mais le téléphone est aussi un outil : dictionnaire, calculatrice, recherches. L''école devrait apprendre aux jeunes à bien l''utiliser au lieu de le cacher. » <em>Yanis, parent d''élève</em></p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le harcèlement en ligne : bắt nạt trên mạng\n• reculer (verbe) : giảm, lùi lại\n• se servir de : sử dụng\n• par défaut : mặc định\n• excessif (adjectif) : quá mức","explications":"• Phần tóm tắt 40 à 60 mots: mỗi người một câu, viết lại bằng lời mình, không chép.\n• Phần ý kiến 80 à 120 mots: nêu lập trường, một lý do, một ví dụ, một câu kết.","kyNang":"TCF-PE-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T12:00:04.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe05q01', 'lo52tcfpe05', 1, 'qcm', 'Que pense Sandrine ?', '{"options":["Les élèves utilisent beaucoup trop la calculatrice.","Le téléphone est un très bon outil pour travailler en classe.","L''interdiction a amélioré la vie des élèves."]}'::jsonb, '{"answer":2}'::jsonb, 'Sandrine kể từ khi cấm, học sinh « se parlent à nouveau » và bắt nạt trên mạng « ont aussi diminué ».'),
  ('lo52tcfpe05q02', 'lo52tcfpe05', 2, 'qcm', 'Que propose Yanis ?', '{"options":["Interdire le téléphone dans tous les collèges de France.","Éduquer les jeunes à bien l''utiliser.","Remplacer les téléphones par des ordinateurs portables."]}'::jsonb, '{"answer":1}'::jsonb, 'Yanis viết « L''école devrait apprendre aux jeunes à bien l''utiliser ».'),
  ('lo52tcfpe05q03', 'lo52tcfpe05', 3, 'qcm', 'Quelle phrase résume correctement les deux points de vue ?', '{"options":["Yanis pense que le harcèlement en ligne a complètement disparu.","Sandrine et Yanis veulent interdire le téléphone.","Alors que Sandrine approuve l''interdiction, Yanis y voit un outil."]}'::jsonb, '{"answer":2}'::jsonb, '« Alors que » nối hai ý trái ngược: đúng cách tóm tắt ở phần đầu tâche 3, mỗi người một vế.'),
  ('lo52tcfpe05q04', 'lo52tcfpe05', 4, 'qcm', 'Dans la partie opinion, que faut-il éviter ?', '{"options":["Recopier des phrases des documents.","Donner un exemple tiré de votre expérience.","Annoncer votre avis avec « À mon avis »."]}'::jsonb, '{"answer":0}'::jsonb, 'Phần ý kiến phải bằng lời của bạn; câu chép lại từ tài liệu không chứng minh được trình độ. Mở ý bằng « À mon avis » là cách tốt.'),
  ('lo52tcfpe05q05', 'lo52tcfpe05', 5, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 180 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Vous participez à un forum sur le thème : « Faut-il interdire les téléphones portables à l''école ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Depuis que notre collège a interdit les portables, les élèves se parlent à nouveau pendant la récréation. Les cas de harcèlement en ligne ont aussi diminué. » <em>Sandrine, professeure de mathématiques</em></p><p><strong>Document 2</strong> : « Interdire, c''est facile. Mais le téléphone est aussi un outil : dictionnaire, calculatrice, recherches. L''école devrait apprendre aux jeunes à bien l''utiliser au lieu de le cacher. » <em>Yanis, parent d''élève</em></p>","tache":3}'::jsonb, '{"model":"Pour Sandrine, professeure, l''interdiction des portables au collège a eu des effets positifs : les élèves communiquent davantage et le harcèlement en ligne a reculé. Yanis, parent d''élève, pense au contraire que le téléphone est un outil utile et que l''école devrait apprendre aux jeunes à s''en servir.\nÀ mon avis, ces deux positions ne s''opposent pas complètement. Je suis favorable à l''interdiction pendant les récréations, car les jeunes ont besoin de moments sans écran pour se parler et jouer. En revanche, interdire totalement le téléphone en classe me semble excessif. Par exemple, dans mon lycée, nous utilisions une application de dictionnaire pendant les cours de langues, sous le contrôle du professeur, et c''était très efficace. La meilleure solution serait donc une règle claire : téléphone rangé par défaut, mais utilisé quand l''enseignant le demande."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-3 #2 Écriture TCF : la semaine de quatre jours (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe06', 'practice', 'Écriture TCF : la semaine de quatre jours', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Le journal de votre ville ouvre un débat : « Faut-il travailler moins pour vivre mieux ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Dans mon entreprise, nous travaillons quatre jours par semaine depuis un an. Je suis moins fatigué, je passe plus de temps avec mes enfants, et je suis plus efficace au travail. » <em>Karim, informaticien</em></p><p><strong>Document 2</strong> : « La semaine de quatre jours, c''est bien pour les bureaux. Mais dans un hôpital ou un restaurant, qui va travailler le cinquième jour ? Il faudrait embaucher, et beaucoup d''entreprises n''en ont pas les moyens. » <em>Hélène, directrice d''une petite entreprise</em></p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• embaucher (verbe) : tuyển dụng\n• avoir les moyens de : có khả năng (tài chính)\n• réservé (adjectif) : dè dặt\n• concilier (verbe) : dung hoà\n• imposer (verbe) : áp đặt","explications":"• Tâche 3 đòi SO SÁNH: dùng alors que, tandis que, au contraire để nối hai người.\n• Ý kiến hay nhất thường nhận phần đúng của cả hai bên rồi đề xuất một giải pháp.","kyNang":"TCF-PE-3","vong":"on","thuTu":2}'::jsonb, '2026-11-16T12:00:05.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe06q01', 'lo52tcfpe06', 1, 'qcm', 'Selon Karim, quel est l''avantage de la semaine de quatre jours ?', '{"options":["Un salaire plus élevé et des primes chaque mois.","Plus de temps libre et plus d''efficacité.","Des vacances d''été plus longues pour toute la famille."]}'::jsonb, '{"answer":1}'::jsonb, 'Karim: « je passe plus de temps avec mes enfants, et je suis plus efficace au travail ».'),
  ('lo52tcfpe06q02', 'lo52tcfpe06', 2, 'qcm', 'Quel problème Hélène soulève-t-elle ?', '{"options":["Ce modèle ne convient pas à tous les métiers.","Les salariés travaillent moins bien.","Les bureaux ferment trop tôt."]}'::jsonb, '{"answer":0}'::jsonb, 'Hélène hỏi « dans un hôpital ou un restaurant, qui va travailler le cinquième jour ? ».'),
  ('lo52tcfpe06q03', 'lo52tcfpe06', 3, 'qcm', 'Quel connecteur introduit bien votre opinion ?', '{"options":["D''après le document 1,","Selon Hélène,","Pour ma part,"]}'::jsonb, '{"answer":2}'::jsonb, '« Pour ma part » mở phần ý kiến riêng; « Selon Hélène » và « D''après le document 1 » dẫn ý người khác, dùng ở phần tóm tắt.'),
  ('lo52tcfpe06q04', 'lo52tcfpe06', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 180 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Le journal de votre ville ouvre un débat : « Faut-il travailler moins pour vivre mieux ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Dans mon entreprise, nous travaillons quatre jours par semaine depuis un an. Je suis moins fatigué, je passe plus de temps avec mes enfants, et je suis plus efficace au travail. » <em>Karim, informaticien</em></p><p><strong>Document 2</strong> : « La semaine de quatre jours, c''est bien pour les bureaux. Mais dans un hôpital ou un restaurant, qui va travailler le cinquième jour ? Il faudrait embaucher, et beaucoup d''entreprises n''en ont pas les moyens. » <em>Hélène, directrice d''une petite entreprise</em></p>","tache":3}'::jsonb, '{"model":"Karim, informaticien, travaille quatre jours par semaine et y voit surtout des avantages : moins de fatigue, plus de temps en famille et une meilleure efficacité. Hélène, cheffe d''entreprise, est plus réservée : selon elle, ce modèle ne peut pas s''appliquer partout, car certains secteurs devraient embaucher.\nPour ma part, je pense que la semaine de quatre jours est une bonne idée, mais qu''elle ne doit pas être imposée à tout le monde. Dans les métiers de bureau, elle permet de mieux concilier vie professionnelle et vie privée, et les salariés reposés font moins d''erreurs. Cependant, Hélène a raison : un petit restaurant ne peut pas fermer un jour de plus ni payer un employé supplémentaire. On pourrait donc laisser chaque secteur choisir son organisation. L''essentiel est de trouver un équilibre entre le bien-être des salariés et la santé des entreprises."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-4 #1 Écriture TCF : les trois tâches en 60 minutes (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe07', 'practice', 'Écriture TCF : les trois tâches en 60 minutes', 'TCF', array['Écriture']::text[], 'practice', null, 60, '<p><strong>Comme au TCF :</strong> écrivez les trois tâches en 60 minutes. Conseil : environ 15 minutes pour la tâche 1, 20 pour la tâche 2, 25 pour la tâche 3.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une grève : cuộc đình công\n• une assurance annulation : bảo hiểm huỷ chuyến\n• la gratuité : sự miễn phí\n• un contribuable : người đóng thuế\n• l''entretien (nom masculin) : việc bảo dưỡng","explications":"• Chia giờ khoảng 15, 20, 25 phút cho tâche 1, 2, 3, chừa 5 phút đọc lại.\n• Đếm từ bằng mắt theo dòng: một dòng viết tay khoảng 10 từ, nên tâche 1 cần 6 đến 12 dòng.","kyNang":"TCF-PE-4","vong":"chot","thuTu":1}'::jsonb, '2026-11-16T12:00:06.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe07q01', 'lo52tcfpe07', 1, 'open', 'Tâche 1 : écrivez votre texte (60 à 120 mots).', '{"doc":"<p><strong>Sujet</strong> : Un(e) ami(e) francophone va passer un week-end dans votre ville. Vous lui écrivez un message pour lui proposer un programme : lieux à visiter, restaurant, activité. (60 mots minimum, 120 mots maximum)</p>","tache":1}'::jsonb, '{"model":"Coucou Sarah !\nJe suis trop contente que tu viennes ce week-end ! Voici mon programme. Samedi matin, on visitera la vieille ville et sa cathédrale, puis on montera à la tour de l''horloge : la vue est magnifique. À midi, je t''emmène dans un petit restaurant de spécialités locales, près du marché. L''après-midi, si le temps le permet, on louera des vélos pour faire le tour du lac. Dimanche, on pourra se reposer ou aller au musée, comme tu veux. Ça te va ?\nÀ samedi !\nMai"}'::jsonb, null),
  ('lo52tcfpe07q02', 'lo52tcfpe07', 2, 'open', 'Tâche 2 : écrivez votre texte (120 à 150 mots).', '{"doc":"<p><strong>Sujet</strong> : Vous écrivez sur un blog de voyage : vous racontez un voyage qui s''est mal passé et vous expliquez ce que vous en avez appris. (120 mots minimum, 150 mots maximum)</p>","tache":2}'::jsonb, '{"model":"L''été dernier, j''ai organisé un voyage de trois jours en Bretagne avec deux amis. Tout semblait parfait : le train était réservé, l''hôtel aussi. Malheureusement, le jour du départ, une grève a supprimé notre train. Nous avons dû louer une voiture à la dernière minute, beaucoup plus chère que prévu. Ensuite, arrivés à l''hôtel, nous avons découvert que notre réservation avait été annulée par erreur. Nous avons passé la première nuit dans une auberge de jeunesse bruyante.\nPourtant, ce voyage raté m''a beaucoup appris. Aujourd''hui, je prends toujours une assurance annulation et je vérifie mes réservations la veille. Surtout, j''ai compris que l''essentiel, c''est l''ambiance : malgré les problèmes, nous avons beaucoup ri, et c''est mon meilleur souvenir de vacances."}'::jsonb, null),
  ('lo52tcfpe07q03', 'lo52tcfpe07', 3, 'open', 'Tâche 3 : écrivez votre texte (120 à 180 mots).', '{"doc":"<p><strong>Sujet</strong> : Un site d''information ouvre un débat : « Les musées doivent-ils être gratuits ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Les musées gratuits attirent des visiteurs qui n''y seraient jamais allés : familles modestes, jeunes, curieux. La culture doit être accessible à tous. » <em>Paul, guide-conférencier</em></p><p><strong>Document 2</strong> : « Un musée coûte cher : gardiens, restauration des œuvres, chauffage. Si l''entrée est gratuite, ce sont les impôts de tous qui paient, même pour ceux qui ne visitent jamais de musée. » <em>Maryse, élue municipale</em></p>","tache":3}'::jsonb, '{"model":"Paul, guide-conférencier, défend la gratuité des musées, car elle permet à des publics modestes ou jeunes de découvrir la culture. Maryse, élue, rappelle au contraire qu''un musée coûte cher et que, sans billet, ce sont tous les contribuables qui paient.\nÀ mon avis, une gratuité totale n''est pas la meilleure solution, mais l''accès doit rester facile. Je trouve juste que les touristes et les adultes qui en ont les moyens paient leur entrée, car l''entretien des œuvres exige beaucoup d''argent. En revanche, les jeunes, les étudiants et les demandeurs d''emploi devraient entrer gratuitement. Dans ma ville, le musée est gratuit le premier dimanche du mois : ce jour-là, on voit beaucoup de familles qui ne viendraient pas autrement. Ce système me semble un bon équilibre entre l''accès à la culture et le financement des musées."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-1 #3 Écriture TCF : message aux voisins (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe08', 'practice', 'Écriture TCF : message aux voisins', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Samedi prochain, vous organisez une fête chez vous pour votre anniversaire. Vous écrivez un message à vos voisins pour les prévenir, vous excuser à l''avance pour le bruit et les inviter à passer. (60 mots minimum, 120 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• prévenir (verbe) : báo trước\n• s''excuser à l''avance : xin lỗi trước\n• au plus tard : muộn nhất\n• être le bienvenu : được hoan nghênh","explications":"• Đề có ba việc (prévenir, s''excuser, inviter): viết mỗi việc ít nhất một câu rõ ràng.\n• Thông tin cụ thể (ngày, giờ, số căn hộ) làm tin nhắn tự nhiên và đủ ý.","isPremium":true,"price":19000,"kyNang":"TCF-PE-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-16T12:00:07.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe08q01', 'lo52tcfpe08', 1, 'qcm', 'Quel est le premier but du message ?', '{"options":["Prévenir les voisins de la fête.","Se plaindre du bruit fait par les voisins.","Demander aux voisins de garder vos enfants."]}'::jsonb, '{"answer":0}'::jsonb, 'Đề nói « pour les prévenir »: báo trước cho hàng xóm.'),
  ('lo52tcfpe08q02', 'lo52tcfpe08', 2, 'qcm', 'Quel ton faut-il employer ?', '{"options":["Aimable et poli.","Très officiel, comme une lettre administrative.","Familier, avec des abréviations de SMS."]}'::jsonb, '{"answer":0}'::jsonb, 'Viết cho « vos voisins »: thân thiện, lịch sự, dùng « vous ».'),
  ('lo52tcfpe08q03', 'lo52tcfpe08', 3, 'qcm', 'Quelle phrase répond à la troisième demande du sujet ?', '{"options":["La fête commencera vers vingt heures, chez moi au deuxième étage.","N''hésitez pas à passer boire un verre !","Je suis désolé pour le bruit."]}'::jsonb, '{"answer":1}'::jsonb, 'Yêu cầu thứ ba là « les inviter à passer »: câu mời « N''hésitez pas à passer » đáp đúng ý này.'),
  ('lo52tcfpe08q04', 'lo52tcfpe08', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (60 à 120 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Samedi prochain, vous organisez une fête chez vous pour votre anniversaire. Vous écrivez un message à vos voisins pour les prévenir, vous excuser à l''avance pour le bruit et les inviter à passer. (60 mots minimum, 120 mots maximum)</p>","tache":1}'::jsonb, '{"model":"Chers voisins,\nSamedi prochain, le 14 juin, je fête mon anniversaire à la maison avec une vingtaine d''amis. La soirée commencera vers vingt heures et se terminera au plus tard à une heure du matin. Je m''excuse à l''avance pour le bruit : nous ferons attention, surtout après minuit. Si vous avez un problème, n''hésitez pas à frapper à ma porte, au deuxième étage. Et surtout, si vous voulez, passez boire un verre avec nous, vous êtes les bienvenus !\nBonne semaine,\nThanh, appartement 2B"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-1 #4 Écriture TCF : courriel au propriétaire (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe09', 'practice', 'Écriture TCF : courriel au propriétaire', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Le chauffage de votre appartement ne fonctionne plus depuis trois jours. Vous écrivez un courriel à votre propriétaire pour décrire le problème, expliquer les conséquences et lui demander d''intervenir rapidement. (60 mots minimum, 120 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une panne : sự hỏng hóc\n• un radiateur : lò sưởi\n• attraper un rhume : bị cảm lạnh\n• intervenir (verbe) : can thiệp, đến xử lý","explications":"• Email phàn nàn: mô tả (chuyện gì) → hậu quả (ảnh hưởng ra sao) → yêu cầu (muốn gì, khi nào).\n• Cho biết thời gian mình có mặt giúp yêu cầu cụ thể và dễ thực hiện.","isPremium":true,"price":19000,"kyNang":"TCF-PE-1","vong":"on","thuTu":4}'::jsonb, '2026-11-16T12:00:08.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe09q01', 'lo52tcfpe09', 1, 'qcm', 'À qui écrivez-vous et quel registre utiliser ?', '{"options":["Au propriétaire, avec un registre poli et formel.","À un voisin, avec un registre très familier et des abréviations.","À un ami, avec un registre familier."]}'::jsonb, '{"answer":0}'::jsonb, 'Người nhận là « votre propriétaire »: lịch sự, dùng « vous », câu chào trang trọng.'),
  ('lo52tcfpe09q02', 'lo52tcfpe09', 2, 'qcm', 'Que faut-il expliquer en plus du problème ?', '{"options":["Le prix de votre loyer mensuel.","Vos projets pour les vacances d''hiver.","Les conséquences de la panne."]}'::jsonb, '{"answer":2}'::jsonb, 'Đề yêu cầu « expliquer les conséquences » (hậu quả của việc hỏng sưởi).'),
  ('lo52tcfpe09q03', 'lo52tcfpe09', 3, 'qcm', 'Quelle formule de politesse convient pour terminer ?', '{"options":["Salut, à bientôt !","À plus, bisous !","Je vous remercie par avance. Cordialement."]}'::jsonb, '{"answer":2}'::jsonb, 'Gửi chủ nhà: « Je vous remercie par avance. Cordialement. » vừa lịch sự vừa đúng kiểu email.'),
  ('lo52tcfpe09q04', 'lo52tcfpe09', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (60 à 120 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Le chauffage de votre appartement ne fonctionne plus depuis trois jours. Vous écrivez un courriel à votre propriétaire pour décrire le problème, expliquer les conséquences et lui demander d''intervenir rapidement. (60 mots minimum, 120 mots maximum)</p>","tache":1}'::jsonb, '{"model":"Objet : panne de chauffage\nMonsieur Martin,\nJe vous écris car le chauffage de l''appartement ne fonctionne plus depuis lundi. Les radiateurs restent froids, même au maximum. Avec les températures actuelles, il fait moins de quinze degrés dans le salon, et ma fille de deux ans a déjà attrapé un rhume. Je dois utiliser un petit radiateur électrique, ce qui va augmenter ma facture. Pourriez-vous envoyer un technicien le plus rapidement possible ? Je suis disponible tous les jours après dix-sept heures.\nJe vous remercie par avance.\nCordialement,\nNgoc Anh Tran"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-1 #5 Écriture TCF : organiser un départ (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe10', 'practice', 'Écriture TCF : organiser un départ', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Votre collègue Sophie quitte l''entreprise à la fin du mois. Vous écrivez un message à toute l''équipe pour proposer d''organiser une petite fête, expliquer ce que vous avez prévu et demander à chacun de participer. (60 mots minimum, 120 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un pot de départ : tiệc chia tay\n• à hauteur de : ở mức\n• un bon (cadeau) : phiếu quà tặng\n• une surprise : điều bất ngờ","explications":"• Tin nhắn cho nhóm: nêu ngày, giờ, địa điểm ngay đầu.\n• Kết bằng việc cụ thể mỗi người cần làm và hạn chót.","isPremium":true,"price":19000,"kyNang":"TCF-PE-1","vong":"on","thuTu":5}'::jsonb, '2026-11-16T12:00:09.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe10q01', 'lo52tcfpe10', 1, 'qcm', 'Qui sont les destinataires ?', '{"options":["Toute l''équipe, sauf Sophie.","Le directeur de l''entreprise, pour demander un budget.","Sophie seulement, pour l''inviter."]}'::jsonb, '{"answer":0}'::jsonb, 'Đề nói « un message à toute l''équipe »; vì là tiệc chia tay bất ngờ, không gửi cho Sophie.'),
  ('lo52tcfpe10q02', 'lo52tcfpe10', 2, 'qcm', 'Que devez-vous expliquer ?', '{"options":["Le nom de la personne qui va remplacer Sophie.","Ce que vous avez prévu pour la fête.","Pourquoi Sophie quitte l''entreprise."]}'::jsonb, '{"answer":1}'::jsonb, 'Đề yêu cầu « expliquer ce que vous avez prévu ».'),
  ('lo52tcfpe10q03', 'lo52tcfpe10', 3, 'qcm', 'Comment « demander à chacun de participer » ?', '{"options":["Obliger tout le monde à rester tard le soir.","Proposer une petite somme pour un cadeau.","Exiger que chacun apporte un plat cher."]}'::jsonb, '{"answer":1}'::jsonb, '« demander à chacun de participer »: mời góp một khoản nhỏ hoặc một món là cách lịch sự.'),
  ('lo52tcfpe10q04', 'lo52tcfpe10', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (60 à 120 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Votre collègue Sophie quitte l''entreprise à la fin du mois. Vous écrivez un message à toute l''équipe pour proposer d''organiser une petite fête, expliquer ce que vous avez prévu et demander à chacun de participer. (60 mots minimum, 120 mots maximum)</p>","tache":1}'::jsonb, '{"model":"Bonjour à tous,\nComme vous le savez, Sophie nous quitte le 30 juin après huit ans dans l''équipe. Je vous propose d''organiser un petit pot de départ le vendredi 27 juin à 17 h, dans la salle de réunion. J''ai prévu de commander des gâteaux et des boissons, et d''acheter un cadeau : un bon pour un week-end à la mer, car elle adore voyager. Pour le cadeau, pourriez-vous participer à hauteur de dix euros ? Vous pouvez me donner l''argent avant mercredi. Surtout, ne dites rien à Sophie, c''est une surprise !\nMerci à tous,\nDavid"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-1 #6 Écriture TCF : demande d'informations (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe11', 'practice', 'Écriture TCF : demande d''informations', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Vous voulez suivre des cours de français le soir. Vous écrivez un courriel à une école de langues pour vous présenter rapidement, expliquer votre objectif et demander des informations sur les cours (horaires, prix, niveau). (60 mots minimum, 120 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le niveau actuel : trình độ hiện tại\n• un test de niveau : bài kiểm tra xếp lớp\n• en cours d''année : giữa năm học\n• la nationalité : quốc tịch","explications":"• Câu hỏi trong email trang trọng: « Pourriez-vous m''indiquer… », « Est-il possible de… ».\n• Mỗi câu hỏi nhắm một thông tin đề yêu cầu (giờ, giá, trình độ).","isPremium":true,"price":19000,"kyNang":"TCF-PE-1","vong":"chot","thuTu":6}'::jsonb, '2026-11-16T12:00:10.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe11q01', 'lo52tcfpe11', 1, 'qcm', 'Combien de parties le courriel doit-il contenir ?', '{"options":["Une seule : la liste des questions.","Trois : présentation, objectif, questions.","Deux : la présentation de vous-même et le paiement des cours."]}'::jsonb, '{"answer":1}'::jsonb, 'Đề có ba việc: « vous présenter rapidement », « expliquer votre objectif » và « demander des informations ».'),
  ('lo52tcfpe11q02', 'lo52tcfpe11', 2, 'qcm', 'Comment doit être la présentation ?', '{"options":["Très détaillée, avec tout votre parcours.","Courte.","Absente, l''école n''en a pas besoin."]}'::jsonb, '{"answer":1}'::jsonb, 'Đề ghi « vous présenter rapidement »: một hai câu là đủ.'),
  ('lo52tcfpe11q03', 'lo52tcfpe11', 3, 'qcm', 'Quelle question est la plus adaptée ?', '{"options":["C''est combien, les cours, hein ?","Tu peux m''appeler ce soir ?","Quels sont les horaires des cours du soir ?"]}'::jsonb, '{"answer":2}'::jsonb, 'Gửi trường học cần câu hỏi lịch sự, đúng chủ đề « horaires, prix, niveau ».'),
  ('lo52tcfpe11q04', 'lo52tcfpe11', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (60 à 120 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Vous voulez suivre des cours de français le soir. Vous écrivez un courriel à une école de langues pour vous présenter rapidement, expliquer votre objectif et demander des informations sur les cours (horaires, prix, niveau). (60 mots minimum, 120 mots maximum)</p>","tache":1}'::jsonb, '{"model":"Objet : cours de français du soir\nMadame, Monsieur,\nJe m''appelle Hoang, j''ai trente-deux ans et je travaille comme ingénieur à Lyon depuis six mois. Je souhaite améliorer mon français pour passer le TCF l''année prochaine, car je veux demander la nationalité. Mon niveau actuel est environ B1. Pourriez-vous m''indiquer les horaires de vos cours du soir et leur prix ? Proposez-vous un test de niveau avant l''inscription ? Enfin, est-il possible de commencer en cours d''année ?\nJe vous remercie de votre réponse.\nCordialement,\nHoang Minh"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-2 #3 Écriture TCF : mon premier emploi (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe12', 'practice', 'Écriture TCF : mon premier emploi', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Un site d''orientation pour les jeunes publie des témoignages sur le thème « Mon premier emploi ». Vous racontez votre premier travail et vous expliquez ce qu''il vous a appris. (120 mots minimum, 150 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un petit boulot : việc làm thêm\n• une commande : đơn gọi món\n• mécontent (adjectif) : không hài lòng\n• être à l''aise : thoải mái\n• avec le recul : nhìn lại","explications":"• Kết bài bằng một lời khuyên cho người đọc (« à tous les jeunes ») phù hợp với trang định hướng.\n• Đoạn bài học nên có 2 hoặc 3 ý cụ thể, không chỉ « j''ai beaucoup appris ».","isPremium":true,"price":19000,"kyNang":"TCF-PE-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-16T12:00:11.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe12q01', 'lo52tcfpe12', 1, 'qcm', 'À qui s''adresse le témoignage ?', '{"options":["Aux clients de votre premier employeur.","À des jeunes qui cherchent leur voie.","À votre ancien patron."]}'::jsonb, '{"answer":1}'::jsonb, 'Bài đăng trên « Un site d''orientation pour les jeunes »: người đọc là bạn trẻ đang định hướng nghề.'),
  ('lo52tcfpe12q02', 'lo52tcfpe12', 2, 'qcm', 'Quelles sont les deux parties attendues ?', '{"options":["Le récit du travail et ce qu''il vous a appris.","Le salaire exact et les horaires précis de votre premier travail.","Votre CV et une lettre de motivation."]}'::jsonb, '{"answer":0}'::jsonb, 'Đề đòi « vous racontez votre premier travail » và « vous expliquez ce qu''il vous a appris ».'),
  ('lo52tcfpe12q03', 'lo52tcfpe12', 3, 'qcm', 'Quel connecteur introduit bien la partie « leçon » ?', '{"options":["Tout d''abord, je suis né en…","Pour commencer, voici mon adresse.","Avec le recul, je comprends que…"]}'::jsonb, '{"answer":2}'::jsonb, '« Avec le recul » (nhìn lại) mở phần rút ra bài học.'),
  ('lo52tcfpe12q04', 'lo52tcfpe12', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 150 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Un site d''orientation pour les jeunes publie des témoignages sur le thème « Mon premier emploi ». Vous racontez votre premier travail et vous expliquez ce qu''il vous a appris. (120 mots minimum, 150 mots maximum)</p>","tache":2}'::jsonb, '{"model":"À dix-huit ans, j''ai trouvé mon premier emploi dans une pizzeria de mon quartier, pendant les vacances d''été. Je prenais les commandes au téléphone et je servais les clients en salle. Les premiers jours ont été difficiles : je me trompais dans les commandes et je n''osais pas parler aux clients mécontents. Mais la patronne m''a beaucoup aidé, et au bout d''un mois, je me sentais à l''aise.\nAvec le recul, je comprends que ce petit travail m''a appris l''essentiel. J''ai découvert l''importance de l''organisation et du travail en équipe. J''ai surtout appris à garder mon calme face aux problèmes. Aujourd''hui, je suis infirmier, et ces qualités me servent chaque jour. Alors, à tous les jeunes : n''ayez pas peur des petits boulots, ils forment plus qu''on ne le croit !"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-2 #4 Écriture TCF : une fête de mon pays (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe13', 'practice', 'Écriture TCF : une fête de mon pays', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Un forum international demande aux participants de présenter une fête traditionnelle de leur pays. Vous racontez comment vous avez célébré cette fête la dernière fois et vous dites ce qu''elle représente pour vous. (120 mots minimum, 150 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le Nouvel An lunaire : Tết âm lịch\n• la veille : đêm trước\n• les pétards : pháo\n• les retrouvailles : sự đoàn tụ\n• les ancêtres : tổ tiên","explications":"• Người đọc nước ngoài: giải thích ngắn từ riêng (« le Têt, le Nouvel An lunaire »).\n• Đoạn cảm nghĩ mở bằng « Pour moi, … représente avant tout… ».","isPremium":true,"price":19000,"kyNang":"TCF-PE-2","vong":"on","thuTu":4}'::jsonb, '2026-11-16T12:00:12.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe13q01', 'lo52tcfpe13', 1, 'qcm', 'Qui va lire le texte ?', '{"options":["Le gouvernement de votre pays.","Seulement des personnes de votre famille.","Des personnes de différents pays."]}'::jsonb, '{"answer":2}'::jsonb, 'Đây là « Un forum international »: người đọc không biết lễ hội, cần giải thích rõ.'),
  ('lo52tcfpe13q02', 'lo52tcfpe13', 2, 'qcm', 'Quel temps utiliser pour raconter la dernière fête ?', '{"options":["Le futur simple seulement.","Le passé composé et l''imparfait.","Le présent du subjonctif."]}'::jsonb, '{"answer":1}'::jsonb, 'Đề nói « la dernière fois »: chuyện đã qua.'),
  ('lo52tcfpe13q03', 'lo52tcfpe13', 3, 'qcm', 'Que faut-il ajouter au récit ?', '{"options":["La liste de toutes les fêtes du monde.","Ce que la fête représente pour vous.","Le prix des billets d''avion pour votre pays."]}'::jsonb, '{"answer":1}'::jsonb, 'Đề đòi « vous dites ce qu''elle représente pour vous ».'),
  ('lo52tcfpe13q04', 'lo52tcfpe13', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 150 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Un forum international demande aux participants de présenter une fête traditionnelle de leur pays. Vous racontez comment vous avez célébré cette fête la dernière fois et vous dites ce qu''elle représente pour vous. (120 mots minimum, 150 mots maximum)</p>","tache":2}'::jsonb, '{"model":"Au Vietnam, la fête la plus importante est le Têt, le Nouvel An lunaire. L''année dernière, je suis rentré à Huê pour le célébrer avec ma famille. Pendant une semaine, nous avons nettoyé et décoré la maison avec des fleurs de pêcher. La veille du Nouvel An, toute la famille s''est réunie autour d''un grand repas, avec le gâteau de riz traditionnel. À minuit, nous avons écouté les pétards et les enfants ont reçu des enveloppes rouges avec un peu d''argent.\nPour moi, le Têt représente avant tout les retrouvailles. Depuis que je vis en France, je ne vois ma famille qu''une fois par an, et ce moment est précieux. C''est aussi l''occasion de remercier nos ancêtres et de commencer l''année avec de bonnes résolutions."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-2 #5 Écriture TCF : un service public (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe14', 'practice', 'Écriture TCF : un service public', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Le journal de votre ville demande aux habitants de partager une expérience avec un service public (hôpital, mairie, bibliothèque, transports…). Vous racontez cette expérience et vous donnez votre avis sur la qualité du service, avec une proposition d''amélioration. (120 mots minimum, 150 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• renouveler (verbe) : gia hạn\n• un titre de séjour : thẻ cư trú\n• un guichet : quầy giao dịch\n• un créneau : khung giờ\n• globalement : nhìn chung","explications":"• Ý kiến cân bằng: một điểm tốt, một điểm cần cải thiện, rồi đề xuất.\n• Đề xuất bắt đầu bằng « Je propose donc de… » nối tự nhiên với phần chê.","isPremium":true,"price":19000,"kyNang":"TCF-PE-2","vong":"on","thuTu":5}'::jsonb, '2026-11-16T12:00:13.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe14q01', 'lo52tcfpe14', 1, 'qcm', 'Combien d''éléments le texte doit-il contenir ?', '{"options":["Deux : l''avis et le nom des employés.","Trois : récit, avis, proposition.","Un seul : le récit de l''expérience."]}'::jsonb, '{"answer":1}'::jsonb, 'Đề đòi kể « cette expérience », nêu « votre avis » và đưa « une proposition d''amélioration ».'),
  ('lo52tcfpe14q02', 'lo52tcfpe14', 2, 'qcm', 'Votre avis doit-il être négatif ?', '{"options":["Oui, il faut toujours critiquer le service.","Non, il peut être positif ou négatif.","Non, il faut rester totalement neutre."]}'::jsonb, '{"answer":1}'::jsonb, 'Đề chỉ nói « votre avis sur la qualité du service »: khen hay chê đều được, miễn có lý do.'),
  ('lo52tcfpe14q03', 'lo52tcfpe14', 3, 'qcm', 'Quelle proposition est la plus réaliste ?', '{"options":["Rendre tous les services gratuits pour tous.","Supprimer complètement le service public.","Ouvrir le service un soir par semaine."]}'::jsonb, '{"answer":2}'::jsonb, 'Đề xuất cụ thể, khả thi thuyết phục hơn ý cực đoan.'),
  ('lo52tcfpe14q04', 'lo52tcfpe14', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 150 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Le journal de votre ville demande aux habitants de partager une expérience avec un service public (hôpital, mairie, bibliothèque, transports…). Vous racontez cette expérience et vous donnez votre avis sur la qualité du service, avec une proposition d''amélioration. (120 mots minimum, 150 mots maximum)</p>","tache":2}'::jsonb, '{"model":"Le mois dernier, j''ai dû renouveler mon titre de séjour à la préfecture. J''avais pris rendez-vous en ligne trois semaines à l''avance. Le jour venu, l''accueil était organisé : un agent m''a orienté vers le bon guichet et je n''ai attendu que vingt minutes. L''employée a été patiente et m''a expliqué clairement les documents qui manquaient.\nGlobalement, je suis satisfait de ce service, qui s''est beaucoup amélioré. Cependant, prendre rendez-vous reste difficile : les créneaux disparaissent en quelques minutes, et beaucoup de personnes n''ont pas accès à internet. Je propose donc d''ouvrir une ligne téléphonique pour les rendez-vous, et un guichet sans rendez-vous un soir par semaine pour les personnes qui travaillent. Ce serait un vrai progrès pour tous les usagers."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-2 #6 Écriture TCF : un livre qui m'a marqué (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe15', 'practice', 'Écriture TCF : un livre qui m''a marqué', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Le blog de la médiathèque de votre quartier publie une rubrique « Le livre qui m''a marqué ». Vous présentez un livre que vous avez lu, vous racontez dans quelles circonstances vous l''avez découvert et vous expliquez pourquoi vous le recommandez. (120 mots minimum, 150 mots maximum)</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• intitulé (adjectif) : có tựa đề\n• par curiosité : vì tò mò\n• lâcher (verbe) : buông\n• émouvant (adjectif) : cảm động\n• se reconnaître dans : thấy mình trong","explications":"• Chia ba đoạn đúng ba việc của đề: dễ cho người chấm thấy bài đủ ý.\n• Lời khuyên có hai lý do nối bằng « D''abord… Ensuite… ».","isPremium":true,"price":19000,"kyNang":"TCF-PE-2","vong":"chot","thuTu":6}'::jsonb, '2026-11-16T12:00:14.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe15q01', 'lo52tcfpe15', 1, 'qcm', 'Combien de tâches le sujet demande-t-il ?', '{"options":["Deux : donner le prix du livre et la biographie complète de son auteur.","Une seule : résumer toute l''histoire du livre.","Trois : présenter, raconter la découverte, recommander."]}'::jsonb, '{"answer":2}'::jsonb, 'Đề có ba việc: « vous présentez un livre », « vous racontez dans quelles circonstances » và « vous expliquez pourquoi vous le recommandez ».'),
  ('lo52tcfpe15q02', 'lo52tcfpe15', 2, 'qcm', 'Faut-il raconter toute l''histoire du livre ?', '{"options":["Non, une courte présentation suffit.","Oui, chapitre par chapitre.","Oui, avec tous les détails et la fin."]}'::jsonb, '{"answer":0}'::jsonb, 'Giới thiệu ngắn để còn chỗ cho phần kể và phần khuyên; kể hết truyện sẽ vượt 150 từ.'),
  ('lo52tcfpe15q03', 'lo52tcfpe15', 3, 'qcm', 'Quelle phrase sert bien la recommandation ?', '{"options":["Je le conseille à tous ceux qui aiment les histoires vraies.","Le livre a 320 pages.","Je l''ai acheté dans une petite librairie de mon quartier, l''an dernier."]}'::jsonb, '{"answer":0}'::jsonb, 'Lời khuyên nêu đối tượng người đọc phù hợp: « Je le conseille à tous ceux qui… ».'),
  ('lo52tcfpe15q04', 'lo52tcfpe15', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 150 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Le blog de la médiathèque de votre quartier publie une rubrique « Le livre qui m''a marqué ». Vous présentez un livre que vous avez lu, vous racontez dans quelles circonstances vous l''avez découvert et vous expliquez pourquoi vous le recommandez. (120 mots minimum, 150 mots maximum)</p>","tache":2}'::jsonb, '{"model":"Le livre qui m''a le plus marqué est un roman intitulé « Le Pays des oranges », d''une autrice canadienne. Il raconte l''histoire d''une jeune femme qui quitte son village pour étudier en ville et qui doit apprendre à vivre entre deux cultures.\nJe l''ai découvert il y a deux ans, pendant un long voyage en train. Une passagère l''avait oublié sur son siège. J''ai commencé à le lire par curiosité, et je ne l''ai plus lâché jusqu''à l''arrivée.\nJe recommande ce livre pour deux raisons. D''abord, le style est simple mais très émouvant, donc il est accessible même aux lecteurs qui apprennent le français. Ensuite, beaucoup de personnes qui ont quitté leur pays se reconnaîtront dans l''héroïne. Je le conseille à tous ceux qui aiment les histoires de vie !"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-3 #3 Écriture TCF : coder à l'école (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe16', 'practice', 'Écriture TCF : coder à l''école', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Un site d''éducation pose la question : « Faut-il apprendre à coder dès l''école primaire ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Le numérique est partout. Apprendre à coder tôt, c''est comprendre comment fonctionnent les outils que l''on utilise chaque jour, et se préparer aux métiers de demain. » <em>Lucie, ingénieure</em></p><p><strong>Document 2</strong> : « À l''école primaire, les enfants ont d''abord besoin de bien lire, écrire et compter. Ajouter le code, c''est surcharger des programmes déjà trop chargés. » <em>Bernard, instituteur</em></p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• surcharger (verbe) : làm quá tải\n• maîtriser (verbe) : nắm vững\n• ludique (adjectif) : mang tính vui chơi\n• une fin en soi : mục đích tự thân\n• concilier (verbe) : dung hoà","explications":"• Tóm tắt: nghề nghiệp của người nói + ý chính, viết lại bằng từ của mình.\n• Ý kiến thuyết phục khi đồng ý một phần với bên kia (« je suis d''accord avec Bernard : … »).","isPremium":true,"price":19000,"kyNang":"TCF-PE-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-16T12:00:15.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe16q01', 'lo52tcfpe16', 1, 'qcm', 'Quel argument Lucie avance-t-elle ?', '{"options":["Le code remplace les mathématiques.","Comprendre les outils numériques et préparer l''avenir.","Les enfants doivent d''abord apprendre à bien lire et à bien écrire."]}'::jsonb, '{"answer":1}'::jsonb, 'Lucie viết « comprendre comment fonctionnent les outils » và « se préparer aux métiers de demain ».'),
  ('lo52tcfpe16q02', 'lo52tcfpe16', 2, 'qcm', 'Que craint Bernard ?', '{"options":["Que les programmes soient trop chargés.","Que les enfants n''aiment pas les ordinateurs.","Que les métiers de demain disparaissent."]}'::jsonb, '{"answer":0}'::jsonb, 'Bernard nói thêm môn lập trình là « surcharger des programmes déjà trop chargés ».'),
  ('lo52tcfpe16q03', 'lo52tcfpe16', 3, 'qcm', 'Quelle phrase résume bien les deux positions ?', '{"options":["Lucie veut enseigner le code tôt, tandis que Bernard préfère les bases.","Bernard est ingénieur et Lucie est institutrice.","Lucie et Bernard veulent tous deux plus d''heures de mathématiques."]}'::jsonb, '{"answer":0}'::jsonb, '« tandis que » nối hai ý trái ngược, mỗi người một vế, đúng cách tóm tắt.'),
  ('lo52tcfpe16q04', 'lo52tcfpe16', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 180 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Un site d''éducation pose la question : « Faut-il apprendre à coder dès l''école primaire ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Le numérique est partout. Apprendre à coder tôt, c''est comprendre comment fonctionnent les outils que l''on utilise chaque jour, et se préparer aux métiers de demain. » <em>Lucie, ingénieure</em></p><p><strong>Document 2</strong> : « À l''école primaire, les enfants ont d''abord besoin de bien lire, écrire et compter. Ajouter le code, c''est surcharger des programmes déjà trop chargés. » <em>Bernard, instituteur</em></p>","tache":3}'::jsonb, '{"model":"Pour Lucie, ingénieure, apprendre à coder dès l''école primaire permet de comprendre les outils numériques du quotidien et de préparer les métiers de demain. Bernard, instituteur, estime au contraire que les enfants doivent d''abord maîtriser la lecture, l''écriture et le calcul, et que le code surchargerait les programmes.\nÀ mon avis, il est possible de concilier les deux points de vue. Il ne s''agit pas d''ajouter une matière, mais d''intégrer le code de façon ludique dans les cours existants. Par exemple, programmer un petit robot pour qu''il suive un chemin fait travailler la logique et les mathématiques. Mon neveu a fait cette activité en CM1, et il a enfin compris les angles ! En revanche, je suis d''accord avec Bernard : les bases restent prioritaires. Le code doit donc rester un outil au service des apprentissages fondamentaux, pas une fin en soi."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-3 #4 Écriture TCF : l'uniforme scolaire (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe17', 'practice', 'Écriture TCF : l''uniforme scolaire', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Un magazine pour parents ouvre un débat : « Faut-il imposer l''uniforme à l''école ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Avec l''uniforme, plus de concours de marques. Les élèves sont tous égaux, et les familles modestes ne se sentent plus jugées. » <em>Isabelle, mère de trois enfants</em></p><p><strong>Document 2</strong> : « L''adolescence est l''âge où l''on construit sa personnalité. Imposer les mêmes vêtements à tous, c''est empêcher les jeunes de s''exprimer. Et l''uniforme coûte cher. » <em>Théo, lycéen</em></p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un concours de marques : cuộc đua hàng hiệu\n• modeste (adjectif) : khiêm tốn, thu nhập thấp\n• une tenue : trang phục\n• la scolarité : thời đi học\n• peser sur : đè nặng lên","explications":"• Dùng « Certes, … mais… » để nhượng bộ: điểm cộng cho tiêu chí lập luận.\n• Trả lời từng lý lẽ của bên kia (ở đây là « coût ») làm ý kiến chặt chẽ.","isPremium":true,"price":19000,"kyNang":"TCF-PE-3","vong":"on","thuTu":4}'::jsonb, '2026-11-16T12:00:16.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe17q01', 'lo52tcfpe17', 1, 'qcm', 'Selon Isabelle, quel est l''avantage de l''uniforme ?', '{"options":["Il coûte moins cher que les vêtements de marque.","Il permet aux jeunes d''exprimer leur personnalité.","Il réduit les différences sociales visibles."]}'::jsonb, '{"answer":2}'::jsonb, 'Isabelle nói « Les élèves sont tous égaux, et les familles modestes ne se sentent plus jugées ».'),
  ('lo52tcfpe17q02', 'lo52tcfpe17', 2, 'qcm', 'Quels sont les deux arguments de Théo ?', '{"options":["L''expression de soi et le coût.","Le confort et la mode.","L''égalité et la sécurité."]}'::jsonb, '{"answer":0}'::jsonb, 'Théo nói uniforme « empêcher les jeunes de s''exprimer » và « l''uniforme coûte cher ».'),
  ('lo52tcfpe17q03', 'lo52tcfpe17', 3, 'qcm', 'Quel connecteur convient pour introduire une concession dans votre opinion ?', '{"options":["Tout d''abord…","En conclusion…","Certes, … mais…"]}'::jsonb, '{"answer":2}'::jsonb, '« Certes, … mais… » là cấu trúc nhượng bộ: thừa nhận ý bên kia rồi phản bác.'),
  ('lo52tcfpe17q04', 'lo52tcfpe17', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 180 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Un magazine pour parents ouvre un débat : « Faut-il imposer l''uniforme à l''école ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Avec l''uniforme, plus de concours de marques. Les élèves sont tous égaux, et les familles modestes ne se sentent plus jugées. » <em>Isabelle, mère de trois enfants</em></p><p><strong>Document 2</strong> : « L''adolescence est l''âge où l''on construit sa personnalité. Imposer les mêmes vêtements à tous, c''est empêcher les jeunes de s''exprimer. Et l''uniforme coûte cher. » <em>Théo, lycéen</em></p>","tache":3}'::jsonb, '{"model":"Isabelle, mère de famille, défend l''uniforme : selon elle, il supprime la compétition entre marques et protège les familles modestes du jugement des autres. Théo, lycéen, s''y oppose, car il empêcherait les adolescents d''exprimer leur personnalité et représenterait une dépense importante.\nPersonnellement, je suis plutôt favorable à une tenue commune, mais simple. Certes, l''adolescence est une période où l''on cherche son style, mais l''école n''est pas le seul lieu pour s''exprimer : le week-end et les loisirs offrent beaucoup de liberté. Au Vietnam, j''ai porté l''uniforme pendant toute ma scolarité, et je n''ai jamais eu le sentiment de perdre ma personnalité. Au contraire, le matin, je n''avais pas à choisir mes vêtements ! Pour répondre à l''argument du coût, l''école pourrait proposer des tenues à prix réduit ou d''occasion. Ainsi, l''uniforme favoriserait l''égalité sans peser sur le budget des familles."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-3 #5 Écriture TCF : les vols courts (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe18', 'practice', 'Écriture TCF : les vols courts', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Un journal en ligne pose la question : « Faut-il interdire les vols en avion quand le train fait le même trajet en moins de quatre heures ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Un trajet en avion pollue beaucoup plus qu''en train. Quand une alternative rapide existe, continuer à prendre l''avion n''a plus de sens face à l''urgence climatique. » <em>Amélie, militante écologiste</em></p><p><strong>Document 2</strong> : « Le train coûte souvent plus cher que l''avion, et beaucoup de petites villes ne sont pas bien desservies. Interdire les vols pénaliserait d''abord les familles et les régions isolées. » <em>Patrick, maire d''une petite ville</em></p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une alternative : giải pháp thay thế\n• l''urgence climatique : tình trạng khẩn cấp khí hậu\n• desservi (participe) : có tuyến giao thông tới\n• pénaliser (verbe) : gây thiệt thòi\n• réunir des conditions : đủ điều kiện","explications":"• Ý kiến có điều kiện (« oui, mais seulement si… ») là cách hay để dung hoà hai bên.\n• Ví dụ có con số cụ thể (giá vé) làm lập luận thuyết phục, nhưng đừng bịa số không hợp lý.","isPremium":true,"price":19000,"kyNang":"TCF-PE-3","vong":"on","thuTu":5}'::jsonb, '2026-11-16T12:00:17.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe18q01', 'lo52tcfpe18', 1, 'qcm', 'Sur quoi Amélie fonde-t-elle sa position ?', '{"options":["Le manque de gares dans les régions.","Le prix élevé des billets de train.","La pollution causée par l''avion."]}'::jsonb, '{"answer":2}'::jsonb, 'Amélie nói « Un trajet en avion pollue beaucoup plus qu''en train ».'),
  ('lo52tcfpe18q02', 'lo52tcfpe18', 2, 'qcm', 'Qui serait pénalisé selon Patrick ?', '{"options":["Les compagnies aériennes.","Les familles et les régions isolées.","Les militants écologistes."]}'::jsonb, '{"answer":1}'::jsonb, 'Patrick viết cấm bay « pénaliserait d''abord les familles et les régions isolées ».'),
  ('lo52tcfpe18q03', 'lo52tcfpe18', 3, 'qcm', 'Quelle phrase de synthèse est correcte ?', '{"options":["Amélie veut supprimer ces vols pour le climat, alors que Patrick craint leurs effets sociaux.","Patrick pense que l''avion pollue moins que le train.","Amélie et Patrick souhaitent augmenter le prix du train."]}'::jsonb, '{"answer":0}'::jsonb, '« alors que » đặt mỗi người một vế: Amélie vì khí hậu, Patrick lo hậu quả xã hội.'),
  ('lo52tcfpe18q04', 'lo52tcfpe18', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 180 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Un journal en ligne pose la question : « Faut-il interdire les vols en avion quand le train fait le même trajet en moins de quatre heures ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Un trajet en avion pollue beaucoup plus qu''en train. Quand une alternative rapide existe, continuer à prendre l''avion n''a plus de sens face à l''urgence climatique. » <em>Amélie, militante écologiste</em></p><p><strong>Document 2</strong> : « Le train coûte souvent plus cher que l''avion, et beaucoup de petites villes ne sont pas bien desservies. Interdire les vols pénaliserait d''abord les familles et les régions isolées. » <em>Patrick, maire d''une petite ville</em></p>","tache":3}'::jsonb, '{"model":"Amélie, militante écologiste, souhaite interdire les vols courts lorsqu''un train rapide existe, car l''avion pollue bien davantage. Patrick, maire d''une petite ville, s''y oppose : le train est souvent plus cher et mal adapté aux régions isolées, qui seraient les premières pénalisées.\nSelon moi, l''interdiction est justifiée, mais seulement si le train devient une vraie solution pour tous. Il est vrai que l''urgence climatique impose de réduire les vols inutiles. Cependant, on ne peut pas demander aux familles de payer deux fois plus cher pour voyager. Par exemple, l''été dernier, un billet de train pour quatre personnes entre Paris et Marseille coûtait près de quatre cents euros, contre deux cents en avion. L''État devrait donc d''abord baisser le prix du train et améliorer les lignes vers les petites villes. Une fois ces conditions réunies, interdire les vols courts serait à la fois écologique et juste."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-3 #6 Écriture TCF : les réseaux sociaux (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe19', 'practice', 'Écriture TCF : les réseaux sociaux', 'TCF', array['Écriture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> lisez le sujet, répondez aux questions de préparation, puis écrivez votre texte en respectant le nombre de mots. Après l''envoi, l''IA évalue votre texte selon les critères du TCF et vous montre une copie modèle.</p>', '<p><strong>Sujet</strong> : Un forum de discussion propose le thème : « Les réseaux sociaux rapprochent-ils les gens ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Grâce aux réseaux sociaux, je parle chaque jour avec ma famille restée au Brésil. Sans eux, l''exil serait beaucoup plus difficile. » <em>Carla, étudiante</em></p><p><strong>Document 2</strong> : « On a des centaines d''amis en ligne, mais on ne voit plus personne. Les réseaux remplacent les vraies rencontres par des échanges superficiels. » <em>Gérard, psychologue</em></p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''exil (nom masculin) : cuộc sống xa xứ\n• supportable (adjectif) : chịu đựng được\n• superficiel (adjectif) : hời hợt\n• au lieu de : thay vì\n• compléter (verbe) : bổ sung","explications":"• Câu ý kiến cân bằng ngắn gọn: « rapprochent ceux qui sont loin, mais peuvent éloigner ceux qui sont proches ».\n• Kết bằng hành động cá nhân cụ thể giúp bài tự nhiên, có dấu ấn riêng.","isPremium":true,"price":19000,"kyNang":"TCF-PE-3","vong":"chot","thuTu":6}'::jsonb, '2026-11-16T12:00:18.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe19q01', 'lo52tcfpe19', 1, 'qcm', 'Quelle expérience Carla décrit-elle ?', '{"options":["Rencontrer de nouveaux amis brésiliens dans sa ville universitaire.","Garder le contact avec sa famille à l''étranger.","Trouver un emploi grâce aux réseaux."]}'::jsonb, '{"answer":1}'::jsonb, 'Carla viết « je parle chaque jour avec ma famille restée au Brésil ».'),
  ('lo52tcfpe19q02', 'lo52tcfpe19', 2, 'qcm', 'Que reproche Gérard aux réseaux sociaux ?', '{"options":["Ils coûtent trop cher aux utilisateurs.","Ils remplacent les vraies rencontres.","Ils sont interdits dans certains pays."]}'::jsonb, '{"answer":1}'::jsonb, 'Gérard nói mạng xã hội « remplacent les vraies rencontres par des échanges superficiels ».'),
  ('lo52tcfpe19q03', 'lo52tcfpe19', 3, 'qcm', 'Dans la synthèse, comment présenter les deux avis ?', '{"options":["Avec vos propres mots, sans donner encore votre opinion.","En donnant tout de suite votre avis personnel, avant les deux documents.","En recopiant les deux documents mot pour mot."]}'::jsonb, '{"answer":0}'::jsonb, 'Phần tóm tắt chỉ trình bày hai ý bằng lời mình; ý kiến riêng để ở phần sau.'),
  ('lo52tcfpe19q04', 'lo52tcfpe19', 4, 'open', 'Écrivez votre texte en suivant le sujet ci-dessus (120 à 180 mots).', '{"taiLieu":"<p><strong>Sujet</strong> : Un forum de discussion propose le thème : « Les réseaux sociaux rapprochent-ils les gens ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Grâce aux réseaux sociaux, je parle chaque jour avec ma famille restée au Brésil. Sans eux, l''exil serait beaucoup plus difficile. » <em>Carla, étudiante</em></p><p><strong>Document 2</strong> : « On a des centaines d''amis en ligne, mais on ne voit plus personne. Les réseaux remplacent les vraies rencontres par des échanges superficiels. » <em>Gérard, psychologue</em></p>","tache":3}'::jsonb, '{"model":"Pour Carla, étudiante, les réseaux sociaux sont précieux : ils lui permettent de garder un lien quotidien avec sa famille restée au Brésil et rendent l''exil plus supportable. Gérard, psychologue, pense au contraire qu''ils isolent, en remplaçant les rencontres réelles par des relations superficielles.\nÀ mon avis, les réseaux sociaux rapprochent ceux qui sont loin, mais peuvent éloigner ceux qui sont proches. Comme Carla, je vis loin de mes parents, et les appels vidéo me permettent de voir grandir mes neveux. Sans cet outil, je me sentirais beaucoup plus seule. En revanche, je remarque que, lors des repas entre amis, chacun regarde souvent son téléphone au lieu de parler. Tout dépend donc de l''usage que l''on en fait. Les réseaux devraient compléter les relations réelles, et non les remplacer. Pour ma part, j''essaie de laisser mon téléphone dans mon sac quand je suis avec mes amis."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-4 #2 Écriture TCF : trois tâches, sujet 2 (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe20', 'practice', 'Écriture TCF : trois tâches, sujet 2', 'TCF', array['Écriture']::text[], 'practice', null, 60, '<p><strong>Comme au TCF :</strong> écrivez les trois tâches en 60 minutes. Conseil : environ 15 minutes pour la tâche 1, 20 pour la tâche 2, 25 pour la tâche 3.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un portefeuille : ví tiền\n• par discrétion : vì tế nhị\n• un semi-marathon : bán marathon\n• la régularité : sự đều đặn\n• la malbouffe : đồ ăn kém lành mạnh","explications":"• Đọc cả ba đề trước, ghi nhanh vài ý cho mỗi đề, rồi mới viết.\n• Chừa 5 phút cuối để đếm từ và sửa lỗi hoà hợp (giống, số, động từ).","isPremium":true,"price":19000,"kyNang":"TCF-PE-4","vong":"chot","thuTu":2}'::jsonb, '2026-11-16T12:00:19.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe20q01', 'lo52tcfpe20', 1, 'open', 'Tâche 1 : écrivez votre texte (60 à 120 mots).', '{"doc":"<p><strong>Sujet</strong> : Vous avez trouvé un portefeuille dans le bus. Vous écrivez un message sur le groupe de votre quartier pour décrire l''objet, expliquer où et quand vous l''avez trouvé, et dire comment le récupérer. (60 mots minimum, 120 mots maximum)</p>","tache":1}'::jsonb, '{"model":"Bonjour à tous,\nCe matin, vers huit heures, j''ai trouvé un portefeuille dans le bus numéro 12, sur un siège au fond, près de l''arrêt Gambetta. Il est en cuir marron, assez usé, avec une petite étiquette rouge. À l''intérieur, il y a des cartes et un peu d''argent, mais je n''ai pas regardé les noms par discrétion. Si c''est le vôtre, envoyez-moi un message privé en décrivant ce qu''il contient. Je pourrai vous le rendre ce soir après dix-huit heures, ou le déposer à la mairie demain.\nBonne journée,\nLan"}'::jsonb, null),
  ('lo52tcfpe20q02', 'lo52tcfpe20', 2, 'open', 'Tâche 2 : écrivez votre texte (120 à 150 mots).', '{"doc":"<p><strong>Sujet</strong> : Vous écrivez un article pour le site d''une association sportive : vous racontez une compétition ou un défi sportif auquel vous avez participé et vous expliquez ce que cette expérience vous a apporté. (120 mots minimum, 150 mots maximum)</p>","tache":2}'::jsonb, '{"model":"En avril dernier, j''ai participé à mon premier semi-marathon, à Bordeaux. Six mois plus tôt, je ne pouvais pas courir plus de vingt minutes. Je me suis entraînée trois fois par semaine avec les membres de notre club, sous la pluie comme sous le soleil. Le jour de la course, il faisait très chaud. Au quinzième kilomètre, j''ai cru que j''allais abandonner, mais une coureuse inconnue m''a encouragée et nous avons terminé ensemble, en deux heures et cinq minutes.\nCette expérience m''a apporté bien plus qu''une médaille. J''ai découvert que la régularité est plus importante que le talent. J''ai aussi compris la force du groupe : sans le club, je n''aurais jamais tenu. Aujourd''hui, j''ai plus confiance en moi, au travail comme dans la vie. Alors, si vous hésitez à vous lancer, rejoignez-nous !"}'::jsonb, null),
  ('lo52tcfpe20q03', 'lo52tcfpe20', 3, 'open', 'Tâche 3 : écrivez votre texte (120 à 180 mots).', '{"doc":"<p><strong>Sujet</strong> : Un site d''actualité pose la question : « Faut-il interdire la publicité pour la malbouffe à la télévision ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Les enfants regardent des milliers de publicités pour des produits trop sucrés et trop gras. L''obésité infantile progresse : il faut protéger les plus jeunes. » <em>Docteur Lemaire, pédiatre</em></p><p><strong>Document 2</strong> : « Interdire la publicité, c''est priver les chaînes de revenus importants. C''est aux parents d''éduquer leurs enfants, pas à l''État de tout interdire. » <em>Sylvie, directrice d''une chaîne de télévision</em></p>","tache":3}'::jsonb, '{"model":"Le docteur Lemaire, pédiatre, souhaite interdire la publicité pour la malbouffe, car elle influence les enfants et contribue à la hausse de l''obésité infantile. Sylvie, directrice de chaîne, s''y oppose : cette mesure priverait la télévision de revenus et l''éducation alimentaire relève, selon elle, des parents.\nJe pense pour ma part qu''une interdiction aux heures où les enfants regardent la télévision serait justifiée. Bien sûr, les parents ont un rôle essentiel. Mais ils ne peuvent pas lutter seuls contre des publicités conçues par des professionnels pour séduire les enfants. Ma nièce de six ans réclame chaque semaine les céréales qu''elle a vues à la télévision, même si elle ne les aime pas vraiment ! Quant aux chaînes, elles pourraient remplacer ces annonces par des publicités pour des produits plus sains. Protéger la santé des enfants doit passer avant les intérêts économiques."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PE-4 #3 Écriture TCF : trois tâches, sujet 3 (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo52tcfpe21', 'practice', 'Écriture TCF : trois tâches, sujet 3', 'TCF', array['Écriture']::text[], 'practice', null, 60, '<p><strong>Comme au TCF :</strong> écrivez les trois tâches en 60 minutes. Conseil : environ 15 minutes pour la tâche 1, 20 pour la tâche 2, 25 pour la tâche 3.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• se faire pardonner : xin được tha thứ\n• les lettres (études) : ngành văn chương\n• l''espérance de vie : tuổi thọ\n• un chantier : công trường\n• la pénibilité : mức độ nặng nhọc","explications":"• Tâche 1 ngắn nhất: viết nhanh trong 15 phút để dành giờ cho tâche 3.\n• Tâche 3: nếu hết giờ, ưu tiên viết đủ phần ý kiến hơn là chau chuốt phần tóm tắt.","isPremium":true,"price":19000,"kyNang":"TCF-PE-4","vong":"chot","thuTu":3}'::jsonb, '2026-11-16T12:00:20.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo52tcfpe21q01', 'lo52tcfpe21', 1, 'open', 'Tâche 1 : écrivez votre texte (60 à 120 mots).', '{"doc":"<p><strong>Sujet</strong> : Vous ne pouvez pas aller au mariage d''un(e) ami(e). Vous lui écrivez un message pour vous excuser, expliquer la raison et proposer de fêter l''événement autrement. (60 mots minimum, 120 mots maximum)</p>","tache":1}'::jsonb, '{"model":"Chère Julie,\nJe suis vraiment désolée, mais je ne pourrai pas être à ton mariage le 21 septembre. Mon entreprise m''envoie en mission à Montréal pendant deux semaines, et je ne peux pas refuser. Tu sais combien je tenais à être là pour ce jour si important. Pour me faire pardonner, je te propose de vous inviter, Marc et toi, à dîner dans notre restaurant préféré dès mon retour. Tu me raconteras tout et tu me montreras les photos ! Je penserai très fort à vous ce jour-là.\nJe t''embrasse,\nHuong"}'::jsonb, null),
  ('lo52tcfpe21q02', 'lo52tcfpe21', 2, 'open', 'Tâche 2 : écrivez votre texte (120 à 150 mots).', '{"doc":"<p><strong>Sujet</strong> : Le site de votre ancienne école publie des souvenirs d''élèves. Vous racontez un professeur qui vous a marqué et vous expliquez son influence sur votre vie. (120 mots minimum, 150 mots maximum)</p>","tache":2}'::jsonb, '{"model":"Au collège, j''avais un professeur de français, Monsieur Lambert, que je n''oublierai jamais. Le premier jour, il est entré en classe avec une valise pleine de livres et nous a dit : « Ici, on ne lit pas pour avoir une note, on lit pour voyager. » Chaque vendredi, il nous lisait une page d''un roman à voix haute, et toute la classe écoutait en silence. Quand j''avais des difficultés, il restait après le cours pour m''expliquer.\nSon influence a été immense. Grâce à lui, j''ai découvert le plaisir de la lecture, que je n''avais jamais connu à la maison. Plus tard, j''ai choisi des études de lettres, et aujourd''hui, je suis bibliothécaire. Quand je conseille un livre à un enfant, je pense souvent à lui. Merci, Monsieur Lambert, de m''avoir donné le goût des histoires."}'::jsonb, null),
  ('lo52tcfpe21q03', 'lo52tcfpe21', 3, 'open', 'Tâche 3 : écrivez votre texte (120 à 180 mots).', '{"doc":"<p><strong>Sujet</strong> : Un magazine pose la question : « Faut-il travailler jusqu''à 67 ans ? » Vous lisez les deux documents ci-dessous. Vous résumez les deux points de vue (40 à 60 mots), puis vous donnez votre opinion (80 à 120 mots). (120 mots minimum, 180 mots maximum)</p><p><strong>Document 1</strong> : « Nous vivons plus longtemps et en meilleure santé. Il est logique de travailler un peu plus longtemps pour financer les retraites. » <em>Henri, économiste</em></p><p><strong>Document 2</strong> : « Après quarante ans de travail physique, mon corps est usé. Travailler jusqu''à 67 ans, c''est possible dans un bureau, pas sur un chantier. » <em>Joël, maçon</em></p>","tache":3}'::jsonb, '{"model":"Henri, économiste, estime qu''il est logique de travailler plus longtemps, puisque l''espérance de vie augmente et qu''il faut financer les retraites. Joël, maçon, répond que cette solution ne tient pas compte des métiers physiques, qui usent le corps bien avant 67 ans.\nÀ mon avis, les deux arguments sont légitimes, et c''est pourquoi un âge unique pour tous me semble injuste. Il est vrai que notre système de retraites doit être financé. Cependant, un employé de bureau et un maçon ne vieillissent pas de la même façon. Mon père, chauffeur de camion, souffrait du dos dès cinquante-cinq ans, alors que mon oncle, comptable, travaille encore avec plaisir à soixante-cinq ans. Il faudrait donc tenir compte de la pénibilité de chaque métier : permettre aux travailleurs manuels de partir plus tôt, et laisser ceux qui le souhaitent continuer plus longtemps."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
